    "question": "43. Albert performs an experiment.<br>Step 1: He takes 5 ml of blue dilute copper sulphate solution in a test tube, places a thin zinc plate in it and stirs for a few minutes. The blue colour fades and a red precipitate of copper settles down.<br>Step 2: He places copper wire in zinc sulphate solution and shakes it. There is no colour change and no precipitate.<br>Which conclusion is true?",
